// Extrae el mensaje entrante del payload de WhatsApp Cloud API.
// Devuelve [] para eventos sin mensaje (p. ej. estados "sent"/"delivered"/"read").
const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg) return [];

// Deduplicación: Meta puede reenviar el mismo webhook.
const store = $getWorkflowStaticData('global');
store.processed = store.processed || [];
if (store.processed.includes(msg.id)) return [];
store.processed.push(msg.id);
store.processed = store.processed.slice(-500);

const contactName = value.contacts?.[0]?.profile?.name || '';
let text = '';
let needsAI = true;
let directReply = '';

switch (msg.type) {
  case 'text':
    text = msg.text?.body || '';
    break;
  case 'interactive':
    text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
    break;
  case 'button':
    text = msg.button?.text || '';
    break;
  default:
    // Audio, imagen, documento, ubicación, etc.: se avisa al modelo para que responda según el system prompt.
    text = `[El usuario envió un mensaje de tipo "${msg.type}" que el asistente no puede leer.]`;
}

if (!text.trim()) {
  needsAI = false;
  directReply = 'Disculpe, no pude leer su mensaje. ¿Podría escribirnos su consulta en texto, por favor?';
}

return [{
  json: {
    from: msg.from,
    messageId: msg.id,
    contactName,
    phoneNumberId: value.metadata?.phone_number_id,
    text: text.slice(0, 4000),
    needsAI,
    directReply,
  },
}];

// Arma la solicitud al LLM (Ollama o Anthropic, según LLM_PROVIDER) con el historial de la conversación.
const fs = require('fs');
const input = $input.first().json;

const provider = ($env.LLM_PROVIDER || 'ollama').trim().toLowerCase();
if (!['ollama', 'anthropic'].includes(provider)) {
  throw new Error(`LLM_PROVIDER no válido: "${provider}". Use "ollama" o "anthropic".`);
}

// El system prompt (incluido su "Recordatorio final") vive solo en system_prompt.md.
const promptPath = $env.SYSTEM_PROMPT_PATH || '/data/system_prompt.md';
let systemPrompt;
try {
  systemPrompt = fs.readFileSync(promptPath, 'utf8');
} catch (e) {
  throw new Error(`No se pudo leer el system prompt en ${promptPath}: ${e.message}`);
}

// Memoria simple en static data del workflow (solo persiste en ejecuciones de producción).
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};
const maxTurns = parseInt($env.CONVERSATION_MAX_MESSAGES || '20', 10);
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;

let convo = store.conversations[input.from];
if (!convo || Date.now() - convo.updatedAt > ttlMs) {
  convo = { messages: [], updatedAt: Date.now() };
}

const now = new Date().toLocaleString('es-PE', {
  timeZone: $env.BUSINESS_TIMEZONE || 'America/Lima',
  dateStyle: 'full',
  timeStyle: 'short',
});
const nameNote = input.contactName ? ` | Nombre de perfil en WhatsApp: ${input.contactName}` : '';
const currentTurn = `[Contexto del sistema: fecha y hora actual: ${now}${nameNote}]\n\n${input.text}`;
const messages = [...convo.messages, { role: 'user', content: currentTurn }];

let llmBody;
if (provider === 'anthropic') {
  llmBody = {
    model: $env.ANTHROPIC_MODEL || 'claude-sonnet-5-5',
    max_tokens: parseInt($env.ANTHROPIC_MAX_TOKENS || '8000', 10),
    thinking: { type: 'adaptive' },
    output_config: { effort: $env.ANTHROPIC_EFFORT || 'low' },
    // Si un clasificador de seguridad rechaza la solicitud, la API la reintenta en el modelo recomendado.
    fallbacks: 'default',
    system: [{ type: 'text', text: systemPrompt, cache_control: { type: 'ephemeral' } }],
    messages,
  };
} else {
  llmBody = {
    model: $env.OLLAMA_MODEL || 'llama3:latest',
    stream: false,
    keep_alive: $env.OLLAMA_KEEP_ALIVE || '30m',
    options: {
      temperature: parseFloat($env.OLLAMA_TEMPERATURE || '0.3'),
      num_ctx: parseInt($env.OLLAMA_NUM_CTX || '8192', 10),
      num_predict: parseInt($env.OLLAMA_NUM_PREDICT || '512', 10),
    },
    messages: [{ role: 'system', content: systemPrompt }, ...messages],
  };
}

return [{ json: { ...input, provider, llmBody, history: convo.messages, maxTurns } }];

// Procesa la respuesta del LLM (Ollama o Anthropic), extrae el bloque <cita> y actualiza la memoria.
const res = $input.first().json;
const ctx = $('Preparar solicitud LLM').first().json;

const FALLBACK = 'Disculpe, en este momento no puedo procesar su mensaje. Un miembro de nuestro equipo le contactará en horario de atención. Gracias por escribir a JS CONSULTORES Y ABOGADOS.';
const REFUSAL = 'Disculpe, no puedo ayudarle con esa solicitud por este medio. Si lo desea, puedo coordinar una consulta con el equipo del estudio.';

let reply = '';
let ok = false;

if (res.error) {
  // LLM caído, modelo no descargado, clave inválida o tiempo de espera agotado.
  reply = FALLBACK;
} else if (ctx.provider === 'anthropic') {
  if (res.stop_reason === 'refusal') {
    reply = REFUSAL;
  } else if (Array.isArray(res.content)) {
    // Solo bloques de texto: la respuesta puede incluir bloques "thinking" que no se envían.
    reply = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
    ok = true;
  }
} else if (res.message && typeof res.message.content === 'string') {
  reply = res.message.content;
  ok = true;
}

reply = reply.replace(/<think>[\s\S]*?<\/think>/g, '').trim(); // por si se usa un modelo con razonamiento visible
if (!reply) { reply = FALLBACK; ok = false; }

// Extraer la solicitud de cita, tolerando bloques de código alrededor. Si el modelo emitió varios
// bloques se usa el último válido, y se retiran todos del mensaje visible.
const CITA_RE = /(```[a-z]*\s*)?<cita>([\s\S]*?)<\/cita>(\s*```)?/gi;
const parseCita = (raw) => {
  raw = raw.trim();
  try { return JSON.parse(raw); } catch (e) {}
  const obj = raw.match(/\{[\s\S]*\}/);
  try { return obj ? JSON.parse(obj[0]) : { raw }; } catch (e) { return { raw }; }
};
let appointment = null;
for (const m of reply.matchAll(CITA_RE)) {
  const parsed = parseCita(m[2]);
  if (!appointment || !parsed.raw || appointment.raw) appointment = parsed;
}
if (appointment) {
  reply = reply.replace(CITA_RE, '').trim();
}
// Etiquetas <cita> sueltas o sin cerrar: no mostrarlas al usuario.
reply = reply.replace(/<\/?cita>[\s\S]*$/i, '').trim();
if (!reply && appointment) {
  reply = 'Gracias, he registrado su solicitud. Un miembro de nuestro equipo le confirmará la cita en horario de atención.';
} else if (!reply) {
  reply = FALLBACK;
  ok = false;
}

if (reply.length > 4000) reply = reply.slice(0, 3990) + '…';

if (ok) {
  const store = $getWorkflowStaticData('global');
  store.conversations = store.conversations || {};
  const msgs = [
    ...ctx.history,
    { role: 'user', content: ctx.text },
    { role: 'assistant', content: reply },
  ];
  let trimmed = msgs.slice(-ctx.maxTurns);
  if (trimmed.length && trimmed[0].role !== 'user') trimmed = trimmed.slice(1);
  store.conversations[ctx.from] = { messages: trimmed, updatedAt: Date.now() };
}

const u = res.usage || {};
return [{
  json: {
    from: ctx.from,
    phoneNumberId: ctx.phoneNumberId,
    reply,
    appointment,
    hasAppointment: !!appointment,
    provider: ctx.provider,
    usage: {
      input_tokens: u.input_tokens ?? res.prompt_eval_count ?? null,
      output_tokens: u.output_tokens ?? res.eval_count ?? null,
      total_ms: res.total_duration ? Math.round(res.total_duration / 1e6) : null,
    },
  },
}];
